    21→func setupResetTestRepo(t *testing.T) (*git.Repository, plumbing.Hash) {
    22→	t.Helper()
    23→
    24→	dir := t.TempDir()
    25→	repo, err := git.PlainInit(dir, false)
    26→	if err != nil {
    27→		t.Fatalf("failed to init git repo: %v", err)
    28→	}
    29→
    30→	t.Chdir(dir)
    31→	paths.ClearRepoRootCache()
    32→
    33→	// Create initial commit
    34→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
    35→	obj := repo.Storer.NewEncodedObject()
    36→	if err := emptyTree.Encode(obj); err != nil {
    37→		t.Fatalf("failed to encode empty tree: %v", err)
    38→	}
    39→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
    40→	if err != nil {
    41→		t.Fatalf("failed to store empty tree: %v", err)
    42→	}
    43→
    44→	sig := object.Signature{Name: "test", Email: "test@test.com"}
    45→	commit := &object.Commit{
    46→		TreeHash:  emptyTreeHash,
    47→		Author:    sig,
    48→		Committer: sig,
    49→		Message:   "initial commit",
    50→	}
    51→	commitObj := repo.Storer.NewEncodedObject()
    52→	if err := commit.Encode(commitObj); err != nil {
    53→		t.Fatalf("failed to encode commit: %v", err)
    54→	}
    55→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
    56→	if err != nil {
    57→		t.Fatalf("failed to store commit: %v", err)
    58→	}
    59→
    60→	// Create HEAD and master references
    61→	headRef := plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.NewBranchReferenceName("master"))
    62→	if err := repo.Storer.SetReference(headRef); err != nil {
    63→		t.Fatalf("failed to set HEAD: %v", err)
    64→	}
    65→	masterRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("master"), commitHash)
    66→	if err := repo.Storer.SetReference(masterRef); err != nil {
    67→		t.Fatalf("failed to set master: %v", err)
    68→	}
    69→
    70→	return repo, commitHash
    71→}
